-- European Union milestone translations (ES/DE/FR)
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-vida-adopted', 'es', 'El paquete ViDA es adoptado formalmente por el Consejo', 'El Consejo de la UE otorga la aprobación final al paquete IVA en la Era Digital (ViDA) -- una Directiva, un Reglamento y un Reglamento de Ejecución -- tras la nueva consulta al Parlamento Europeo. El paquete se implementa progresivamente hasta enero de 2035.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-vida-force', 'es', 'ViDA entra en vigor', 'El paquete ViDA entra en vigor. A partir de esta fecha, cada Estado miembro puede introducir su propio régimen obligatorio de facturación electrónica doméstica bajo condiciones específicas, sin necesidad de solicitar una excepción separada a la UE, lo que explica por qué varios mandatos nacionales (p. ej., Bélgica, Polonia) han avanzado con sus propios calendarios muy por delante de cualquier fecha a nivel de la UE.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-transpose', 'es', 'ViDA — plazo de transposición del Registro Único de IVA', 'Los Estados miembros deben transponer las disposiciones del Registro Único de IVA (SVR) de la Directiva ViDA a su legislación nacional antes de esta fecha, para que el alcance ampliado de la Ventanilla Única (OSS)/Ventanilla Única de Importación (IOSS) y sus aclaraciones conexas puedan aplicarse desde el 1 de enero de 2027. Este plazo es específico del pilar SVR — es distinto de, y anterior a, los calendarios de transposición del pilar de economía de plataformas de ViDA (2028) y de su pilar de facturación electrónica / Requisitos de Reporte Digital (2030).', '["Si vende bienes o servicios B2C transfronterizos dentro de la UE, confirme que su registro OSS/IOSS cubre el alcance ampliado que entra en vigor en enero de 2027", "Este plazo no exige por sí mismo la facturación electrónica doméstica — los Estados miembros ya pueden introducir sus propios mandatos de facturación electrónica de forma independiente, bajo las excepciones disponibles desde la entrada en vigor de ViDA en abril de 2025", "Siga el calendario de transposición y de facturación electrónica doméstica de su propia autoridad fiscal nacional por separado de este plazo de SVR a nivel de la UE"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-en16931-2026', 'es', 'Se publica la norma semántica revisada EN 16931-1:2026', 'El CEN publica formalmente el modelo de datos semántico revisado para facturación electrónica EN 16931-1:2026, ampliando la norma original centrada en B2G para dar mejor soporte a escenarios B2B complejos antes de los Requisitos de Reporte Digital de 2030 -- añadiendo campos para IBAN, indicadores de triangulación, secuenciación de facturas rectificativas y regímenes de margen de beneficio.', '["Confirme que su proveedor de software de facturación tiene una hoja de ruta para soportar el conjunto de campos ampliado de EN 16931-1:2026"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-platform-svr-2028', 'es', 'ViDA — entrada en vigor de la economía de plataformas y el Registro Único de IVA', 'Las plataformas digitales que facilitan el alquiler de alojamiento de corta duración y el transporte de pasajeros por carretera pasan a ser el proveedor considerado (deemed supplier) a efectos del IVA cuando el proveedor subyacente no repercute el IVA él mismo (por ejemplo, pequeñas empresas o particulares). Las reformas del Registro Único de IVA entran en vigor en toda la UE, y se aplica una inversión del sujeto pasivo obligatoria cuando un proveedor no está establecido ni registrado a efectos del IVA en el Estado miembro de suministro.', '["Si opera una plataforma que entra en el ámbito de aplicación (alquiler de alojamiento de corta duración o transporte de pasajeros por carretera), confirme sus obligaciones de recaudación y remisión del IVA como proveedor considerado", "Si suministra bienes o servicios en un Estado miembro en el que no está registrado a efectos del IVA, confirme si la nueva inversión del sujeto pasivo obligatoria se aplica ahora a sus operaciones", "Evalúe si el modelo ampliado de Registro Único de IVA le permite consolidar los registros que mantiene actualmente en varios Estados miembros"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-drr', 'es', 'ViDA — Requisitos de Reporte Digital transfronterizo', 'La facturación electrónica estructurada y los Requisitos de Reporte Digital (DRR) casi en tiempo real pasan a ser obligatorios en toda la UE para las transacciones B2B transfronterizas. Se elimina el Listado Recapitulativo (Modelo 349) y se sustituye por el DRR.', '["Poder emitir facturas electrónicas conformes con EN 16931 dentro de los 10 días posteriores al hecho imponible en ventas B2B intracomunitarias", "Incorpore el reporte casi en tiempo real a su flujo de facturación antes de la fecha de entrada en vigor", "Retire los procesos del Listado Recapitulativo una vez que el DRR los sustituya"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-align', 'es', 'ViDA — armonización de sistemas nacionales', 'Todos los sistemas nacionales de facturación electrónica y reporte ya existentes (incluidos modelos de compensación consolidados como el SDI de Italia) deben alinearse con la norma armonizada de la UE bajo ViDA.', '["Si opera en un país con su propio sistema de compensación, confirme su plan de alineación con EN 16931/ViDA", "Planifique un modelo de reporte único para todos los mercados de la UE en los que opere"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-vida-adopted', 'de', 'ViDA-Paket wird vom Rat formell verabschiedet', 'Der Rat der EU erteilt nach erneuter Anhörung des Europäischen Parlaments die endgültige Zustimmung zum Paket Mehrwertsteuer im digitalen Zeitalter (ViDA) — bestehend aus einer Richtlinie, einer Verordnung und einer Durchführungsverordnung. Das Paket wird schrittweise bis Januar 2035 umgesetzt.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-vida-force', 'de', 'ViDA tritt in Kraft', 'Das ViDA-Paket tritt in Kraft. Ab diesem Datum dürfen einzelne Mitgliedstaaten unter bestimmten Bedingungen eigene verpflichtende inländische E-Invoicing-Regelungen einführen, ohne einen gesonderten EU-Ausnahmeantrag stellen zu müssen — dies erklärt, warum mehrere nationale Mandate (z. B. Belgien, Polen) mit ihren eigenen Zeitplänen deutlich vor jedem EU-weiten Datum vorangeschritten sind.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-transpose', 'de', 'ViDA — Umsetzungsfrist für die einheitliche USt-Registrierung', 'Die Mitgliedstaaten müssen die Bestimmungen zur einheitlichen USt-Registrierung (Single VAT Registration, SVR) der ViDA-Richtlinie bis zu diesem Datum in nationales Recht umsetzen, damit der erweiterte Anwendungsbereich des One-Stop-Shop (OSS)/Import-One-Stop-Shop (IOSS) und die zugehörigen Klarstellungen ab dem 1. Januar 2027 gelten können. Diese Frist betrifft ausschließlich den SVR-Bereich — sie unterscheidet sich von den Umsetzungsfristen für ViDAs Plattformwirtschafts-Bereich (2028) und den Bereich E-Invoicing/Digitale Meldepflichten (2030) und liegt zeitlich vor diesen.', '["Wenn Sie grenzüberschreitend B2C-Waren oder -Dienstleistungen innerhalb der EU verkaufen, stellen Sie sicher, dass Ihre OSS-/IOSS-Registrierung den ab Januar 2027 geltenden erweiterten Anwendungsbereich abdeckt", "Diese Frist verlangt für sich genommen keine inländische E-Rechnungsstellung — Mitgliedstaaten können bereits seit dem Inkrafttreten von ViDA im April 2025 unabhängig eigene E-Invoicing-Mandate einführen", "Verfolgen Sie den Umsetzungs- und E-Invoicing-Zeitplan Ihrer eigenen nationalen Steuerbehörde getrennt von dieser EU-weiten SVR-Frist"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-en16931-2026', 'de', 'Überarbeiteter semantischer Standard EN 16931-1:2026 veröffentlicht', 'CEN veröffentlicht formell das überarbeitete semantische Datenmodell EN 16931-1:2026 für E-Invoicing und erweitert damit den ursprünglich auf B2G ausgerichteten Standard, um komplexe B2B-Szenarien vor den Digitalen Meldepflichten 2030 besser zu unterstützen — mit neuen Feldern für IBAN, Dreiecksgeschäft-Indikatoren, Rechnungskorrektur-Sequenzierung und Differenzbesteuerung.', '["Stellen Sie sicher, dass Ihr Rechnungssoftware-Anbieter einen Fahrplan zur Unterstützung des erweiterten Feldsatzes von EN 16931-1:2026 hat"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-platform-svr-2028', 'de', 'ViDA — Start der Plattformwirtschafts- und SVR-Regeln', 'Digitale Plattformen, die die kurzfristige Vermietung von Unterkünften und den Personenstraßenverkehr vermitteln, gelten für Mehrwertsteuerzwecke als fiktiver Lieferer, wenn der eigentliche Anbieter selbst keine Mehrwertsteuer erhebt (z. B. Kleinunternehmer oder Privatpersonen). Die Reformen zur einheitlichen USt-Registrierung treten EU-weit in Kraft, und ein verpflichtendes inländisches Reverse-Charge-Verfahren gilt, wenn ein Lieferer im Mitgliedstaat der Lieferung nicht ansässig oder nicht umsatzsteuerlich registriert ist.', '["Wenn Sie eine betroffene Plattform betreiben (kurzfristige Unterkunftsvermietung oder Personenstraßenverkehr), klären Sie Ihre Pflichten zur Erhebung und Abführung der Umsatzsteuer als fiktiver Lieferer", "Wenn Sie Waren oder Dienstleistungen in einem Mitgliedstaat erbringen, in dem Sie nicht umsatzsteuerlich registriert sind, prüfen Sie, ob das neue verpflichtende Reverse-Charge-Verfahren nun auf Ihre Umsätze anwendbar ist", "Prüfen Sie, ob Sie mit dem erweiterten Modell der einheitlichen USt-Registrierung mehrere derzeit gehaltene Registrierungen in verschiedenen Mitgliedstaaten konsolidieren können"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-drr', 'de', 'ViDA — grenzüberschreitende digitale Meldepflichten', 'Strukturiertes E-Invoicing und nahezu Echtzeit-Meldepflichten (Digital Reporting Requirements, DRR) werden EU-weit für grenzüberschreitende B2B-Transaktionen verpflichtend. Die Zusammenfassende Meldung entfällt und wird durch DRR ersetzt.', '["Stellen Sie sicher, dass Sie EN-16931-konforme E-Rechnungen innerhalb von 10 Tagen nach dem Steuertatbestand für innergemeinschaftliche B2B-Verkäufe ausstellen können", "Integrieren Sie die Nahezu-Echtzeit-Meldung frühzeitig in Ihre Rechnungsstellungsprozesse", "Stellen Sie die Prozesse zur Zusammenfassenden Meldung ein, sobald DRR sie ersetzt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-align', 'de', 'ViDA — Harmonisierung nationaler Systeme', 'Alle bereits bestehenden nationalen E-Invoicing- und Meldesysteme (einschließlich etablierter Clearing-Modelle wie Italiens SDI) müssen an den harmonisierten EU-ViDA-Standard angeglichen werden.', '["Falls Sie in einem Land mit eigenem Clearing-System tätig sind, prüfen Sie dessen Plan zur Angleichung an EN 16931/ViDA", "Planen Sie ein einheitliches Meldemodell für alle EU-Märkte, in denen Sie tätig sind"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-vida-adopted', 'fr', 'Le paquet ViDA est formellement adopté par le Conseil', 'Le Conseil de l''UE donne son approbation finale au paquet TVA à l''ère numérique (ViDA) -- une directive, un règlement et un règlement d''exécution -- après une nouvelle consultation du Parlement européen. Le paquet est déployé progressivement jusqu''en janvier 2035.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-vida-force', 'fr', 'ViDA entre en vigueur', 'Le paquet ViDA entre en vigueur. À partir de cette date, chaque État membre peut introduire son propre régime obligatoire de facturation électronique domestique sous certaines conditions, sans avoir besoin d''une dérogation distincte de l''UE -- ce qui explique pourquoi plusieurs mandats nationaux (par exemple, la Belgique, la Pologne) ont avancé selon leurs propres calendriers, bien avant toute échéance à l''échelle de l''UE.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-transpose', 'fr', 'ViDA — échéance de transposition de l''immatriculation unique à la TVA', 'Les États membres doivent transposer les dispositions relatives à l''immatriculation unique à la TVA (Single VAT Registration, SVR) de la directive ViDA dans leur droit national avant cette date, afin que le champ élargi du guichet unique (OSS)/guichet unique à l''importation (IOSS) et les clarifications associées puissent s''appliquer à partir du 1er janvier 2027. Cette échéance concerne spécifiquement le pilier SVR — elle est distincte des calendriers de transposition du pilier économie de plateformes de ViDA (2028) et de son pilier facturation électronique / obligations de déclaration numérique (2030), et leur est antérieure.', '["Si vous vendez des biens ou services B2C transfrontaliers au sein de l''UE, vérifiez que votre immatriculation OSS/IOSS couvre le champ élargi entrant en vigueur en janvier 2027", "Cette échéance n''impose pas en elle-même la facturation électronique domestique — les États membres peuvent déjà introduire leurs propres obligations de facturation électronique de manière indépendante, en vertu des dérogations disponibles depuis l''entrée en vigueur de ViDA en avril 2025", "Suivez le calendrier de transposition et de facturation électronique domestique de votre propre administration fiscale nationale séparément de cette échéance SVR à l''échelle de l''UE"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-en16931-2026', 'fr', 'La norme sémantique révisée EN 16931-1:2026 est publiée', 'Le CEN publie formellement le modèle de données sémantique révisé EN 16931-1:2026 pour la facturation électronique, élargissant la norme initialement axée sur le B2G afin de mieux prendre en charge les scénarios B2B complexes avant les obligations de déclaration numérique de 2030 -- en ajoutant des champs pour l''IBAN, les indicateurs de triangulation, la séquentialisation des factures rectificatives et les régimes de la marge bénéficiaire.', '["Vérifiez que votre fournisseur de logiciel de facturation dispose d''une feuille de route pour prendre en charge l''ensemble de champs élargi d''EN 16931-1:2026"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-platform-svr-2028', 'fr', 'ViDA — entrée en vigueur de l''économie de plateformes et de l''immatriculation unique à la TVA', 'Les plateformes numériques facilitant la location de courte durée et le transport routier de voyageurs deviennent le fournisseur présumé (deemed supplier) aux fins de la TVA lorsque le prestataire sous-jacent ne facture pas lui-même la TVA (par exemple, petites entreprises ou particuliers). Les réformes de l''immatriculation unique à la TVA entrent en vigueur dans toute l''UE, et un mécanisme d''autoliquidation domestique obligatoire s''applique lorsqu''un fournisseur n''est ni établi ni immatriculé à la TVA dans l''État membre de fourniture.', '["Si vous exploitez une plateforme concernée (location de courte durée ou transport routier de voyageurs), vérifiez vos obligations de collecte et de reversement de la TVA en tant que fournisseur présumé", "Si vous fournissez des biens ou services dans un État membre où vous n''êtes pas immatriculé à la TVA, vérifiez si la nouvelle autoliquidation obligatoire s''applique désormais à vos opérations", "Évaluez si le modèle élargi d''immatriculation unique à la TVA vous permet de consolider les immatriculations que vous détenez actuellement dans plusieurs États membres"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-drr', 'fr', 'ViDA — obligations de déclaration numérique transfrontalières', 'La facturation électronique structurée et les obligations de déclaration numérique (DRR) quasi en temps réel deviennent obligatoires dans toute l''UE pour les transactions B2B transfrontalières. L''état récapitulatif est supprimé et remplacé par le DRR.', '["Être en mesure d''émettre des factures électroniques conformes à EN 16931 dans les 10 jours suivant le fait générateur pour les ventes B2B intracommunautaires", "Intégrez la déclaration quasi en temps réel dans votre chaîne de facturation avant la mise en service", "Supprimez les processus liés à l''état récapitulatif une fois que le DRR les remplace"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-align', 'fr', 'ViDA — harmonisation des systèmes nationaux', 'Tous les systèmes nationaux de facturation électronique et de déclaration déjà existants (y compris des modèles de contrôle établis comme le SDI italien) doivent être alignés sur la norme harmonisée ViDA de l''UE.', '["Si vous opérez dans un pays disposant de son propre système de contrôle, vérifiez son plan d''alignement sur EN 16931/ViDA", "Planifiez un modèle de déclaration unique pour tous les marchés de l''UE où vous opérez"]');
